const QUESTIONS_KEY = 'fiendfyre_trivia_questions_v2';
const SETTINGS_KEY = 'fiendfyre_academy_settings_v2';

export const DEFAULT_SETTINGS: AcademySettings = {
  academyName: 'Hogwarts School of Witchcraft & Cyber Defense',
  customLogoUrl: null,
  selectedHouse: 'gryffindor',
  totalSteps: 10, // default 10 stepping stones
  initialTimeSeconds: 55, // balanced stamina bar
  timeBonusCorrect: 8, // +8 seconds
  timePenaltyWrong: 12, // -12 seconds
};

export function getStoredQuestions(): TriviaQuestion[] {
  try {
    const raw = localStorage.getItem(QUESTIONS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length >= 5) {
        return parsed;
      }
    }
  } catch (err) {
    console.error('Error loading trivia questions:', err);
  }
  return DEFAULT_QUESTIONS;
}

export function saveStoredQuestions(questions: TriviaQuestion[]): void {
  try {
    localStorage.setItem(QUESTIONS_KEY, JSON.stringify(questions));
  } catch (err) {
    console.error('Error saving trivia questions:', err);
  }
}

export function resetStoredQuestions(): TriviaQuestion[] {
  try {
    localStorage.removeItem(QUESTIONS_KEY);
  } catch (err) {
    console.error('Error resetting trivia questions:', err);
  }
  return DEFAULT_QUESTIONS;
}

export function getStoredSettings(): AcademySettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      return { 
        ...DEFAULT_SETTINGS, 
        ...parsed, 
        totalSteps: typeof parsed.totalSteps === 'number' && parsed.totalSteps >= 3 && parsed.totalSteps <= 20 ? parsed.totalSteps : 10 
      };
    }
  } catch (err) {
    console.error('Error loading settings:', err);
  }
  return DEFAULT_SETTINGS;
}

export function saveStoredSettings(settings: AcademySettings): void {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch (err) {
    console.error('Error saving settings:', err);
  }
}

/**
 * Returns a randomized set of 10 questions for a single game session
 */
export function getGameQuestionSet(count: number = 10): TriviaQuestion[] {
  const all = [...getStoredQuestions()];
  // Fisher-Yates shuffle
  for (let i = all.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [all[i], all[j]] = [all[j], all[i]];
  }
  return all.slice(0, Math.min(count, all.length));
}
